class Solution:
    def twoSum(self, nums, idx, target, freq):
        target -= nums[idx]
        n = len(nums)
        l, r = idx, n - 1
        count = 0
        while l <= r:
            total = nums[l] + nums[r]

            if total > target:
                r -= 1
            elif total < target:
                l += 1
            else:
                if idx < l < r:
                    count += freq[nums[idx]] * freq[nums[l]] * freq[nums[r]]
                elif idx == l < r:
                    count += freq[nums[idx]] * (freq[nums[l]] - 1) // 2 * freq[nums[r]]
                elif idx < l == r:
                    count += freq[nums[idx]] * freq[nums[l]] * (freq[nums[r]] - 1) // 2
                else:
                    count += freq[nums[idx]] * (freq[nums[l]] - 1) * (freq[nums[r]] - 2)// 6
                r -= 1
                l += 1
        return count


    def threeSumMulti(self, arr: list[int], target: int) -> int:
        freq = Counter(arr)
        nums = sorted(freq.keys())
        n = len(nums)

        ans = 0
        for i in range(n):
            ans += self.twoSum(nums, i, target, freq)

        return ans % (10 ** 9 + 7)
